# -*- coding: utf-8 -*-
"""
Full authentic Bengali translations and word-by-word pairing for Surah 29 (Al-Ankabut) Verses 1 to 69.
"""

s29_translations = {
    1: ("**الم** আলিফ-লাম-মীম (হুরুফে মুকাত্তা‘আত; এর গূঢ় রহস্য আল্লাহই সম্যক অবগত)।", "আলিফ-লাম-মীম।"),
    2: ("**أَحَسِبَ** মানুষ কি ধারণা করেছে； **النَّاسُ** মানুষেরা； **أَنْ يُتْرَكُوا** যে তাদের অব্যাহতি দেওয়া হবে； **أَنْ يَقُولُوا** এ কথা বললেই； **آمَنَّا** আমরা ঈমান এনেছি； **وَهُمْ** অথচ তাদের； **لَا يُفْتَنُونَ** পরীক্ষা করা হবে না?", "মানুষ কি মনে করেছে যে, ‘আমরা ঈমান এনেছি’ এ কথা বললেই তাদের অব্যাহতি দেওয়া হবে, আর তাদের পরীক্ষা করা হবে না?"),
    3: ("**وَلَقَدْ** এবং অবশ্যই； **فَتَنَّا** আমি পরীক্ষা করেছি； **الَّذِينَ** তাদের যারা； **مِنْ قَبْلِهِمْ** তাদের পূর্বে ছিল； **فَلَيَعْلَمَنَّ اللَّهُ** অতঃপর আল্লাহ অবশ্যই প্রকাশ করবেন； **الَّذِينَ صَدَقُوا** যারা সত্য বলেছে； **وَلَيَعْلَمَنَّ** এবং অবশ্যই প্রকাশ করবেন； **الْكَاذِبِينَ** মিথ্যাবাদীদের।", "নিশ্চয় আমি তাদের পূর্ববর্তীদেরও পরীক্ষা করেছি; ফলে আল্লাহ অবশ্যই প্রকাশ করে দেবেন কারা সত্যবাদী এবং কারা মিথ্যাবাদী।"),
    4: ("**أَمْ حَسِبَ** নাকি মনে করেছে； **الَّذِينَ** তারা যারা； **يَعْمَلُونَ** লিপ্ত থাকে； **السَّيِّئَاتِ** মন্দ কাজে； **أَنْ يَسْبِقُونَا** যে তারা আমাকে পরাভূত করবে?； **سَاءَ** কতই না নিকৃষ্ট； **مَا يَحْكُمُونَ** যা তারা ফয়সালা করে!", "নাকি যারা মন্দ কাজ করে তারা মনে করে যে তারা আমার নাগালের বাইরে চলে যাবে? তাদের সিদ্ধান্ত কতই না নিকৃষ্ট!"),
    5: ("**مَنْ كَانَ** যে ব্যক্তি； **يَرْجُو** প্রত্যাশা করে； **لِقَاءَ اللَّهِ** আল্লাহর সাক্ষাৎ； **فَإِنَّ** নিশ্চয়； **أَجَلَ اللَّهِ** আল্লাহর নির্ধারিত সময়； **لَآتٍ** অবশ্যই সমাগত； **وَهُوَ** এবং তিনি； **السَّمِيعُ** সর্বশ্রোতা； **الْعَلِيمُ** সর্বজ্ঞ।", "যে ব্যক্তি আল্লাহর সাক্ষাৎ প্রত্যাশা করে, নিশ্চয় আল্লাহর নির্ধারিত সময় সমাগত; আর তিনি সর্বশ্রোতা, সর্বজ্ঞ।"),
    6: ("**وَمَنْ جَاهَدَ** আর যে সাধনা-সংগ্রাম করে； **فَإِنَّمَا يُجَاهِدُ** সে তো সংগ্রাম করে； **لِنَفْسِهِ** নিজেরই কল্যাণে； **إِنَّ اللَّهَ** নিশ্চয় আল্লাহ； **لَغَنِيٌّ** সম্পূর্ণ অমুখাপেক্ষী； **عَنْ الْعَالَمِينَ** বিশ্ববাসীর থেকে।", "আর যে ব্যক্তি সাধনা ও সংগ্রাম করে, সে তো নিজের কল্যাণের জন্যই সংগ্রাম করে; নিশ্চয় আল্লাহ বিশ্বজাহান থেকে সম্পূর্ণ অমুখাপেক্ষী।"),
    7: ("**وَالَّذِينَ آمَنُوا** আর যারা ঈমান এনেছে； **وَعَمِلُوا** এবং সম্পাদন করেছে； **الصَّالِحَاتِ** সৎকর্মাবলী； **لَنُكَفِّرَنَّ** আমি অবশ্যই মোচন করব； **عَنْهُمْ** তাদের থেকে； **سَيِّئَاتِهِمْ** তাদের পাপসমূহ； **وَلَنَجْزِيَنَّهُمْ** এবং তাদের প্রতিদান দেব； **أَحْسَنَ** সর্বোত্তম； **الَّذِي** যা； **كَانُوا يَعْمَلُونَ** তারা করত।", "আর যারা ঈমান এনেছে এবং সৎকর্ম করেছে, আমি অবশ্যই তাদের পাপসমূহ মোচন করব এবং তারা যা করত তার সর্বোত্তম প্রতিদান দান করব।"),
    8: ("**وَوَصَّيْنَا** আর আমি নির্দেশ দিয়েছি； **الْإِنْسَانَ** মানুষকে； **بِوَالِدَيْهِ** পিতা-মাতার সাথে； **حُسْنًا** সদ্ব্যবহারের； **وَإِنْ جَاهَدَاكَ** তবে তারা চাপ দিলে； **لِتُشْرِكَ بِي** আমার সাথে শরিক করতে； **مَا لَيْسَ لَكَ بِهِ عِلْمٌ** যে বিষয়ে তোমার জ্ঞান নেই； **فَلَا تُطِعْهُمَا** তাদের আনুগত্য করো না； **إِلَيَّ** আমারই কাছে； **مَرْجِعُكُمْ** তোমাদের প্রত্যাবর্তন； **فَأُنَبِّئُكُمْ** অতঃপর আমি জানিয়ে দেব； **بِمَا كُنْتُمْ تَعْمَلُونَ** যা তোমরা করতে।", "আর আমি মানুষকে তার পিতা-মাতার সাথে সদাচরণের নির্দেশ দিয়েছি; তবে তারা যদি তোমার ওপর এমন কিছু শরিক করতে চাপ দেয় যার কোনো জ্ঞান তোমার নেই, তবে তাদের আনুগত্য করবে না। আমারই কাছে তোমাদের প্রত্যাবর্তন, অতঃপর আমি তোমাদের জানিয়ে দেব যা তোমরা করতে।"),
    9: ("**وَالَّذِينَ آمَنُوا** আর যারা ঈমান এনেছে； **وَعَمِلُوا الصَّالِحَاتِ** এবং নেক আমল করেছে； **لَنُدْخِلَنَّهُمْ** আমি অবশ্যই তাদের প্রবিষ্ট করব； **فِي الصَّالِحِينَ** সৎকর্মশীলদের অন্তর্ভুক্ত করে।", "আর যারা ঈমান এনেছে এবং সৎকর্ম করেছে, আমি অবশ্যই তাদেরকে নেককারদের অন্তর্ভুক্ত করব।"),
    10: ("**وَمِنْ النَّاسِ** মানুষের মধ্যে কেউ কেউ； **مَنْ يَقُولُ** যে বলে； **آمَنَّا بِاللَّهِ** আমরা ঈমান এনেছি আল্লাহর প্রতি； **فَإِذَا أُوذِيَ** অতঃপর যখন সে নির্যাতিত হয়； **فِي اللَّهِ** আল্লাহর পথে； **جَعَلَ فِتْنَةَ النَّاسِ** মানুষের নির্যাতনকে মনে করে； **كَعَذَابِ اللَّهِ** আল্লাহর শাস্তির ন্যায়； **وَلَئِنْ جَاءَ نَصْرٌ** আর সাহায্য আসলে； **مِنْ رَبِّكَ** তোমার রবের পক্ষ থেকে； **لَيَقُولُنَّ** তারা অবশ্যই বলে； **إِنَّا كُنَّا مَعَكُمْ** আমরা তো তোমাদের সাথেই ছিলাম； **أَوَلَيْسَ اللَّهُ بِأَعْلَمَ** আল্লাহ কি সম্যক অবগত নন； **بِمَا فِي صُدُورِ الْعَالَمِينَ** যা বিশ্ববাসীর অন্তরে আছে?", "আর মানুষের মধ্যে কেউ কেউ বলে, ‘আমরা আল্লাহর প্রতি ঈমান এনেছি’, কিন্তু যখন আল্লাহর পথে সে নির্যাতিত হয়, তখন সে মানুষের নির্যাতনকে আল্লাহর আযাবের মতো মনে করে; আর তোমার রবের পক্ষ থেকে কোনো বিজয় আসলে তারা নিশ্চিত বলবে, ‘আমরা তো তোমাদের সাথেই ছিলাম।’ বিশ্ববাসীর অন্তরে যা আছে, সে সম্পর্কে কি আল্লাহ সর্বাধিক অবগত নন?"),
    11: ("**وَلَيَعْلَمَنَّ اللَّهُ** আর আল্লাহ অবশ্যই প্রকাশ করবেন； **الَّذِينَ آمَنُوا** যারা সত্য ঈমান এনেছে； **وَلَيَعْلَمَنَّ** এবং অবশ্যই প্রকাশ করবেন； **الْمُنَافِقِينَ** মুনাফিকদের।", "আর আল্লাহ অবশ্যই প্রকাশ করে দেবেন কারা প্রকৃত মুমিন এবং অবশ্যই প্রকাশ করবেন কারা মুনাফিক।"),
    12: ("**وَقَالَ الَّذِينَ كَفَرُوا** কাফিররা বলে； **لِلَّذِينَ آمَنُوا** মুমিনদের লক্ষ্য করে； **اتَّبِعُوا سَبِيلَنَا** আমাদের পথ অনুসরণ করো； **وَلْنَحْمِلْ** আমরা বহন করব； **خَطَايَاكُمْ** তোমাদের পাপসমূহ； **وَمَا هُمْ بِحَامِلِينَ** অথচ তারা বহনকারী নয়； **مِنْ خَطَايَاهُمْ مِنْ شَيْءٍ** তাদের পাপের সামান্যতম； **إِنَّهُمْ لَكَاذِبُونَ** নিশ্চয় তারা চরম মিথ্যাবাদী।", "আর কাফিররা মুমিনদের বলে, ‘তোমরা আমাদের পথ অনুসরণ করো, আমরা তোমাদের পাপভার বহন করব।’ অথচ তারা তাদের পাপের সামান্যতম অংশও বহনকারী নয়; নিশ্চয় তারা চরম মিথ্যাবাদী।"),
    13: ("**وَلَيَحْمِلُنَّ** আর তারা অবশ্যই বহন করবে； **أَثْقَالَهُمْ** নিজেদের পাপভার； **وَأَثْقَالًا مَعَ أَثْقَالِهِمْ** এবং নিজেদের পাপভারের সাথে আরও বহু পাপভার； **وَلَيُسْأَلُنَّ** এবং তাদের জিজ্ঞাসা করা হবে； **يَوْمَ الْقِيَامَةِ** কিয়ামতের দিন； **عَمَّا كَانُوا يَفْتَرُونَ** যা তারা উদ্ভাবন করত।", "আর তারা অবশ্যই নিজেদের পাপভার বহন করবে এবং নিজেদের পাপভারের সাথে আরও বহু পাপভার বহন করবে; আর তারা যে মিথ্যা রচনা করত, কিয়ামতের দিন সে সম্পর্কে অবশ্যই তাদের জিজ্ঞাসাবাদ করা হবে।"),
    14: ("**وَلَقَدْ أَرْسَلْنَا** আর নিশ্চয় আমি পাঠিয়েছিলাম； **نُوحًا** নূহকে； **إِلَى قَوْمِهِ** তার কওমের নিকট； **فَلَبِثَ فِيهِمْ** সে তাদের মাঝে অবস্থান করল； **أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا** পঞ্চাশ কম এক হাজার বছর； **فَأَخَذَهُمُ الطُّوفَانُ** অতঃপর প্লাবন তাদের গ্রাস করল； **وَهُمْ ظَالِمُونَ** যখন তারা ছিল যালেম।", "আর নিশ্চয় আমি নূহকে তার কওমের নিকট পাঠিয়েছিলাম, সে তাদের মধ্যে পঞ্চাশ কম এক হাজার বছর (সাড়ে নয়শত বছর) অবস্থান করেছিল; অতঃপর মহাপ্লাবন তাদের গ্রাস করেছিল, যখন তারা ছিল যালেম।"),
    15: ("**فَأَنْجَيْنَاهُ** অতঃপর আমি তাকে রক্ষা করলাম； **وَأَصْحَابَ السَّفِينَةِ** এবং নৌকার আরোহীদের； **وَجَعَلْنَاهَا** এবং এটিকে বানিয়েছি； **آيَةً** এক শিক্ষণীয় নিদর্শন； **لِلْعَالَمِينَ** বিশ্ববাসীর জন্য।", "অতঃপর আমি তাকে ও নৌকার আরোহীদের রক্ষা করলাম এবং এটিকে বিশ্ববাসীর জন্য এক শিক্ষণীয় নিদর্শন বানালাম।"),
    16: ("**وَإِبْرَاهِيمَ** আর স্মরণ করো ইবরাহীমকে； **إِذْ قَالَ لِقَوْمِهِ** যখন সে তার কওমকে বলল； **اعْبُدُوا اللَّهَ** আল্লাহর ইবাদত করো； **وَاتَّقُوهُ** এবং তাঁকে ভয় করো； **ذَلِكُمْ خَيْرٌ لَكُمْ** এটিই তোমাদের জন্য কল্যাণকর； **إِنْ كُنْتُمْ تَعْلَمُونَ** যদি তোমরা জানতে!", "আর স্মরণ করো ইবরাহীমকে, যখন সে তার কওমকে বলেছিল: তোমরা আল্লাহর ইবাদত করো এবং তাঁকে ভয় করো; এটিই তোমাদের জন্য কল্যাণকর, যদি তোমরা জানতে!"),
    17: ("**إِنَّمَا تَعْبُدُونَ** তোমরা তো উপাসনা করছ； **مِنْ دُونِ اللَّهِ** আল্লাহর পরিবর্তে； **أَوْثَانًا** মূর্তিসমূহের； **وَتَخْلُقُونَ إِفْكًا** এবং মিথ্যা উদ্ভাবন করছ； **إِنَّ الَّذِينَ تَعْبُدُونَ** নিশ্চয় যাদের তোমরা পূজা করো； **لَا يَمْلِكُونَ لَكُمْ رِزْقًا** তারা রিযিক দানের ক্ষমতা রাখে না； **فَابْتَغُوا عِنْدَ اللَّهِ الرِّزْقَ** আল্লাহর কাছেই রিযিক তালাশ করো； **وَاعْبُدُوهُ** তাঁরই ইবাদত করো； **وَاشْكُرُوا لَهُ** তাঁর প্রতি কৃতজ্ঞ হও； **إِلَيْهِ تُرْجَعُونَ** তাঁরই কাছে ফিরে যাবে।", "তোমরা তো আল্লাহর পরিবর্তে কেবল মূর্তিপূজা করছ এবং মিথ্যা রচনা করছ; নিশ্চয় আল্লাহর পরিবর্তে তোমরা যাদের পূজা করো, তারা তোমাদের কোনো রিযিক দানের ক্ষমতা রাখে না। কাজেই তোমরা আল্লাহর কাছেই রিযিক তালাশ করো, তাঁরই ইবাদত করো এবং তাঁরই প্রতি কৃতজ্ঞতা প্রকাশ করো; তাঁরই নিকট তোমাদের ফিরিয়ে আনা হবে।"),
    18: ("**وَإِنْ تُكَذِّبُوا** আর যদি তোমরা প্রত্যাখ্যান করো； **فَقَدْ كَذَّبَ أُمَمٌ** তবে বহু জাতিও প্রত্যাখ্যান করেছিল； **مِنْ قَبْلِكُمْ** তোমাদের পূর্বে； **وَمَا عَلَى الرَّسُولِ** আর রাসূলের ওপর দায়িত্ব নেই； **إِلَّا الْبَلَاغُ الْمُبِينُ** কেবল সুস্পষ্টভাবে পৌঁছে দেওয়া ছাড়া।", "আর যদি তোমরা প্রত্যাখ্যান করো, তবে তোমাদের পূর্ববর্তী বহু জাতিও তো প্রত্যাখ্যান করেছিল; আর সুস্পষ্টভাবে পৌঁছে দেওয়া ছাড়া রাসূলের অন্য কোনো দায়িত্ব নেই।"),
    19: ("**أَوَلَمْ يَرَوْا** তারা কি লক্ষ্য করে না； **كَيْفَ يُبْدِئُ اللَّهُ الْخَلْقَ** কীভাবে আল্লাহ সৃষ্টির সূচনা করেন； **ثُمَّ يُعِيدُهُ** অতঃপর তা পুনরায় সৃষ্টি করবেন； **إِنَّ ذَلِكَ** নিশ্চয় এটি； **عَلَى اللَّهِ يَسِيرٌ** আল্লাহর জন্য সহজ।", "তারা কি লক্ষ্য করে না কীভাবে আল্লাহ সৃষ্টির সূচনা করেন, অতঃপর তা পুনরায় সৃষ্টি করবেন? নিশ্চয় এটি আল্লাহর জন্য অত্যন্ত সহজ।"),
    20: ("**قُلْ سِيرُوا** বলুন: তোমরা ভ্রমণ করো； **فِي الْأَرْضِ** জমিনে； **فَانْظُرُوا** অতঃপর প্রত্যক্ষ করো； **كَيْفَ بَدَأَ الْخَلْقَ** কীভাবে তিনি সৃষ্টি শুরু করেছেন； **ثُمَّ اللَّهُ** অতঃপর আল্লাহ； **يُنْشِئُ النَّشْأَةَ الْآخِرَةَ** পরবর্তী সৃষ্টি উদ্ভব করবেন； **إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ** নিশ্চয় আল্লাহ সর্ববিষয়ে সর্বশক্তিমান।", "বলুন: তোমরা পৃথিবীতে ভ্রমণ করো এবং অবলোকন করো কীভাবে তিনি সৃষ্টির সূচনা করেছেন; অতঃপর আল্লাহই পরবর্তী সৃষ্টি উদ্ভব করবেন। নিশ্চয় আল্লাহ সর্ববিষয়ে সর্বশক্তিমান।"),
    21: ("**يُعَذِّبُ مَنْ يَشَاءُ** তিনি যাকে ইচ্ছা শাস্তি দেন； **وَيَرْحَمُ مَنْ يَشَاءُ** যাকে ইচ্ছা অনুগ্রহ করেন； **وَإِلَيْهِ تُقْلَبُونَ** এবং তাঁরই দিকে প্রত্যাবর্তিত হবে।", "তিনি যাকে ইচ্ছা শাস্তি প্রদান করেন এবং যার প্রতি ইচ্ছা রহমত বর্ষণ করেন; আর তাঁরই সমীপে তোমাদের প্রত্যাবর্তিত করা হবে।"),
    22: ("**وَمَا أَنْتُمْ بِمُعْجِزِينَ** তোমরা পরাভূত করতে পারবে না； **فِي الْأَرْضِ** জমিনে； **وَلَا فِي السَّمَاءِ** এবং আকাশেও নয়； **وَمَا لَكُمْ** আর তোমাদের নেই； **مِنْ دُونِ اللَّهِ** আল্লাহ ছাড়া； **مِنْ وَلِيٍّ** কোনো অভিভাবক； **وَلَا نَصِيرٍ** এবং কোনো সাহায্যকারী।", "আর তোমরা পৃথিবীতে বা আকাশে (আল্লাহকে) অক্ষম ও পরাভূত করতে পারবে না; আর আল্লাহ ছাড়া তোমাদের কোনো অভিভাবক নেই এবং কোনো সাহায্যকারীও নেই।"),
    23: ("**وَالَّذِينَ كَفَرُوا** আর যারা অবিশ্বাস করেছে； **بِآيَاتِ اللَّهِ** আল্লাহর নিদর্শনে； **وَلِقَائِهِ** এবং তাঁর সাক্ষাতে； **أُولَئِكَ يَئِسُوا** তারাই নিরাশ হয়েছে； **مِنْ رَحْمَتِي** আমার রহমত থেকে； **وَأُولَئِكَ لَهُمْ** এবং তাদের জন্য আছে； **عَذَابٌ أَلِيمٌ** যন্ত্রণাদায়ক শাস্তি।", "আর যারা আল্লাহর নিদর্শনাবলী ও তাঁর সাক্ষাতে অবিশ্বাস করে, তারাই আমার রহমত থেকে নিরাশ হয়েছে; আর তাদের জন্যই রয়েছে যন্ত্রণাদায়ক শাস্তি।"),
    24: ("**فَمَا كَانَ جَوَابَ قَوْمِهِ** তার কওমের উত্তর কেবল এই ছিল； **إِلَّا أَنْ قَالُوا** যে তারা বলল； **اقْتُلُوهُ** তাকে হত্যা করো； **أَوْ حَرِّقُوهُ** বা পুড়িয়ে মারো； **فَأَنْجَاهُ اللَّهُ** কিন্তু আল্লাহ তাকে রক্ষা করলেন； **مِنْ النَّارِ** অগ্নিকুণ্ড থেকে； **إِنَّ فِي ذَلِكَ لَآيَاتٍ** নিশ্চয় এতে বহু নিদর্শন আছে； **لِقَوْمٍ يُؤْمِنُونَ** মুমিন সম্প্রদায়ের জন্য।", "অতঃপর তার কওমের উত্তর কেবল এই ছিল যে তারা বলল: তাকে হত্যা করো অথবা তাকে আগুনে পুড়িয়ে মারো! কিন্তু আল্লাহ তাকে অগ্নিকুণ্ড থেকে রক্ষা করলেন। নিশ্চয় এতে মুমিন সম্প্রদায়ের জন্য বহু নিদর্শন রয়েছে।"),
    25: ("**وَقَالَ إِنَّمَا اتَّخَذْتُمْ** সে বলল: তোমরা তো গ্রহণ করেছ； **مِنْ دُونِ اللَّهِ أَوْثَانًا** আল্লাহর পরিবর্তে মূর্তিসমূহকে； **مَوَدَّةَ بَيْنِكُمْ** পরস্পরের ভালোবাসার খাতিরে； **فِي الْحَيَاةِ الدُّنْيَا** পার্থিব জীবনে； **ثُمَّ يَوْمَ الْقِيَامَةِ** অতঃপর কিয়ামতের দিন； **يَكْفُرُ بَعْضُكُمْ بِبَعْضٍ** একে অপরকে অস্বীকার করবে； **وَيَلْعَنُ بَعْضُكُمْ بَعْضًا** একে অপরকে অভিশাপ দেবে； **وَمَأْوَاكُمُ النَّارُ** তোমাদের ঠিকানা জাহান্নাম； **وَمَا لَكُمْ مِنْ نَاصِرِينَ** কোনো সাহায্যকারী থাকবে না।", "আর সে বলল: তোমরা তো পার্থিব জীবনের পারস্পরিক ভালোবাসার সম্পর্কের খাতিরেই আল্লাহর পরিবর্তে মূর্তিসমূহকে গ্রহণ করেছ; অতঃপর কিয়ামতের দিন তোমরা একে অপরকে অস্বীকার করবে এবং একে অপরকে অভিশাপ দেবে; আর তোমাদের ঠিকানা হবে জাহান্নাম এবং তোমাদের কোনো সাহায্যকারী থাকবে না।"),
    26: ("**فَآمَنَ لَهُ لُوطٌ** অতঃপর লূত তার প্রতি ঈমান আনল； **وَقَالَ إِنِّي مُهَاجِرٌ** এবং সে বলল: আমি হিজরত করছি； **إِلَى رَبِّي** আমার রবের উদ্দেশ্যে； **إِنَّهُ هُوَ الْعَزِيزُ الْحَكِيمُ** নিশ্চয় তিনি পরাক্রমশালী, প্রজ্ঞাময়।", "অতঃপর লূত তার প্রতি ঈমান আনল এবং সে বলল: নিশ্চয় আমি আমার রবের উদ্দেশ্যে হিজরত করছি; নিশ্চয় তিনি পরাক্রমশালী, পরম প্রজ্ঞাময়।"),
    27: ("**وَوَهَبْنَا لَهُ** আর আমি তাকে দান করলাম； **إِسْحَاقَ وَيَعْقُوبَ** ইসহাক্ব ও ইয়া‘কূবকে； **وَجَعَلْنَا فِي ذُرِّيَّتِهِ** তার বংশে অব্যাহত রাখলাম； **النُّبُوَّةَ وَالْكِتَابَ** নবুওয়াত ও কিতাব； **وَآتَيْنَاهُ أَجْرَهُ** তাকে তার প্রতিদান দিলাম； **فِي الدُّنْيَا** দুনিয়াতে； **وَإِنَّهُ فِي الْآخِرَةِ** আর আখেরাতে সে； **لَمِنْ الصَّالِحِينَ** সৎকর্মশীলদের অন্যতম।", "আর আমি তাকে দান করলাম ইসহাক্ব ও ইয়া‘কূব এবং তার বংশধরের মধ্যে নবুওয়াত ও কিতাব অব্যাহত রাখলাম, আর দুনিয়াতে তাকে তার প্রতিদান দিয়েছিলাম; আর আখেরাতে সে অবশ্যই নেককারদের অন্তর্ভুক্ত।"),
    28: ("**وَلُوطًا** আর লূতকে পাঠিয়েছিলাম； **إِذْ قَالَ لِقَوْمِهِ** যখন সে তার কওমকে বলল； **إِنَّكُمْ لَتَأْتُونَ الْفَاحِشَةَ** তোমরা এমন চরম অশ্লীল কাজ করছ； **مَا سَبَقَكُمْ بِهَا** তোমাদের পূর্বে যা করেনি； **مِنْ أَحَدٍ** কেউ； **مِنْ الْعَالَمِينَ** বিশ্বজগতের মধ্যে।", "আর স্মরণ করো লূতকে, যখন সে তার কওমকে বলেছিল: তোমরা কি এমন চরম অশ্লীল কাজ করছ, যা তোমাদের পূর্বে বিশ্বজগতের কেউ কখনো করেনি?"),
    29: ("**أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ** তোমরা কি কামতৃপ্তির জন্য পুরুষদের কাছে গমন করছ； **وَتَقْطَعُونَ السَّبِيلَ** এবং পথ ডাকাতি করছ； **وَتَأْتُونَ فِي نَادِيكُمُ الْمُنْكَرَ** এবং মজলিসে গর্হিত কাজ করছ?； **فَمَا كَانَ جَوَابَ قَوْمِهِ** কওমের উত্তর কেবল এই ছিল； **إِلَّا أَنْ قَالُوا** যে তারা বলল； **ائْتِنَا بِعَذَابِ اللَّهِ** আমাদের ওপর আল্লাহর আযাব নিয়ে এসো； **إِنْ كُنْتَ مِنَ الصَّادِقِينَ** যদি তুমি সত্যবাদী হও!", "তোমরা কি পুরুষদের কাছে কামতৃপ্তির জন্য গমন করছ, পথ ডাকাতি করছ এবং নিজেদের প্রকাশ্য মজলিসে গর্হিত কাজ করছ? অতঃপর তার কওমের উত্তর কেবল এই ছিল যে তারা বলল: আমাদের ওপর আল্লাহর আযাব নিয়ে এসো, যদি তুমি সত্যবাদীদের অন্তর্ভুক্ত হও!"),
    30: ("**قَالَ رَبِّ انْصُرْنِي** সে বলল: হে আমার রব! আমাকে সাহায্য করুন； **عَلَى الْقَوْمِ الْمُفْسِدِينَ** এই ফাসাদ সৃষ্টিকারী সম্প্রদায়ের বিরুদ্ধে।", "সে প্রার্থনা করল: হে আমার রব! এই বিপর্যয় সৃষ্টিকারী সম্প্রদায়ের বিরুদ্ধে আমাকে সাহায্য করুন!"),
    31: ("**وَلَمَّا جَاءَتْ رُسُلُنَا** যখন আমার প্রেরিতরা আসল； **إِبْرَاهِيمَ بِالْبُشْرَى** সুসংবাদ নিয়ে ইবরাহীমের কাছে； **قَالُوا إِنَّا مُهْلِكُو** তারা বলল: আমরা ধ্বংস করব； **أَهْلِ هَذِهِ الْقَرْيَةِ** এই জনপদের অধিবাসীদের； **إِنَّ أَهْلَهَا كَانُوا ظَالِمِينَ** নিশ্চয় এর অধিবাসীরা যালেম।", "আর যখন আমার প্রেরিত ফেরেশতাগণ সুসংবাদ নিয়ে ইবরাহীমের নিকট আসল, তখন তারা বলল: আমরা এই জনপদের অধিবাসীদের ধ্বংস করতে যাচ্ছি; নিশ্চয় এর অধিবাসীরা ঘোর যালেম।"),
    32: ("**قَالَ إِنَّ فِيهَا لُوطًا** সে বলল: এতে তো লূতও রয়েছে!； **قَالُوا نَحْنُ أَعْلَمُ** তারা বলল: আমরা ভালো করেই জানি； **بِمَنْ فِيهَا** সেখানে কে আছে； **لَنُنَجِّيَنَّهُ وَأَهْلَهُ** আমরা অবশ্যই তাকে ও পরিবারকে রক্ষা করব； **إِلَّا امْرَأَتَهُ** তার স্ত্রী ব্যতীত； **كَانَتْ مِنَ الْغَابِرِينَ** সে ধ্বংসপ্রাপ্তদের অন্যতম।", "ইবরাহীম বলল: নিশ্চয় এর মধ্যে তো লূতও রয়েছে! তারা বলল: সেখানে কে আছে তা আমরা ভালো করেই জানি; আমরা অবশ্যই তাকে ও তার পরিবারকে রক্ষা করব—তার স্ত্রী ব্যতীত, সে ধ্বংসপ্রাপ্তদের অন্তর্ভুক্ত থাকবে।"),
    33: ("**وَلَمَّا أَنْ جَاءَتْ رُسُلُنَا** আর যখন আমার প্রেরিতরা আসল； **لُوطًا سِيءَ بِهِمْ** লূতের কাছে সে বিষণ্ণ হলো； **وَضَاقَ بِهِمْ ذَرْعًا** এবং নিজেকে অসহায় মনে করল； **وَقَالُوا لَا تَخَفْ** তারা বলল: ভয় পেয়ো না； **وَلَا تَحْزَنْ** এবং দুঃখ কোরো না； **إِنَّا مُنَجُّوكَ وَأَهْلَكَ** আমরা তোমাকে ও পরিবারকে রক্ষা করব； **إِلَّا امْرَأَتَكَ** তোমার স্ত্রী ব্যতীত； **كَانَتْ مِنَ الْغَابِرِينَ** সে ধ্বংসপ্রাপ্তদের অন্যতম।", "আর যখন আমার প্রেরিত ফেরেশতাগণ লূতের নিকট উপস্থিত হলো, তখন সে তাদের কারণে বিষণ্ণ হলো এবং তাদের জন্য নিজেকে অসহায় মনে করল; কিন্তু তারা বলল: ভয় পেয়ো না এবং দুঃখ কোরো না; আমরা অবশ্যই তোমাকে ও তোমার পরিবারকে উদ্ধার করব—তোমার স্ত্রী ব্যতীত, সে ধ্বংসপ্রাপ্তদের অন্তর্ভুক্ত থাকবে।"),
    34: ("**إِنَّا مُنْزِلُونَ** নিশ্চয় আমরা অবতীর্ণ করতে যাচ্ছি； **عَلَى أَهْلِ هَذِهِ الْقَرْيَةِ** এই জনপদের অধিবাসীদের ওপর； **رِجْزًا مِنْ السَّمَاءِ** আকাশ থেকে আযাব； **بِمَا كَانُوا يَفْسُقُونَ** কারণ তারা পাপাচার করত।", "নিশ্চয় আমরা এই জনপদের অধিবাসীদের ওপর আকাশ থেকে ভয়াবহ আযাব অবতীর্ণ করতে যাচ্ছি, কারণ তারা পাপাচার করত।"),
    35: ("**وَلَقَدْ تَرَكْنَا مِنْهَا** আর অবশ্যই আমি রেখে দিয়েছি এতে； **آيَةً بَيِّنَةً** এক সুস্পষ্ট নিদর্শন； **لِقَوْمٍ يَعْقِلُونَ** বোধসম্পন্ন সম্প্রদায়ের জন্য।", "আর অবশ্যই আমি বোধসম্পন্ন সম্প্রদায়ের জন্য এতে এক সুস্পষ্ট নিদর্শন রেখে দিয়েছি।"),
    36: ("**وَإِلَى مَدْيَنَ** আর মাদইয়ানবাসীর প্রতি； **أَخَاهُمْ شُعَيْبًا** তাদের ভাই শু‘আইবকে পাঠিয়েছিলাম； **فَقَالَ يَا قَوْمِ** সে বলল: হে আমার কওম!； **اعْبُدُوا اللَّهَ** আল্লাহর ইবাদত করো； **وَارْجُوا الْيَوْمَ الْآخِرَ** শেষ দিবসের আশা রাখো； **وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ** এবং জমিনে বিপর্যয় সৃষ্টি কোরো না।", "আর মাদইয়ানবাসীর প্রতি আমি তাদের ভাই শু‘আইবকে পাঠিয়েছিলাম; সে বলল: হে আমার কওম! আল্লাহর ইবাদত করো, শেষ দিবসের প্রত্যাশা করো এবং পৃথিবীতে বিপর্যয় সৃষ্টিকারী হয়ে চলো না।"),
    37: ("**فَكَذَّبُوهُ** অতঃপর তারা তাকে মিথ্যাবাদী বলল； **فَأَخَذَتْهُمُ الرَّجْفَةُ** ফলে ভূমিকম্প তাদের পাকড়াও করল； **فَأَصْبَحُوا فِي دَارِهِمْ** তারা নিজ নিজ গৃহে পড়ে রইল； **جَاثِمِينَ** উপুড় হয়ে নিথর অবস্থায়।", "কিন্তু তারা তাকে মিথ্যাবাদী বলল; ফলে এক প্রচণ্ড ভূমিকম্প তাদের পাকড়াও করল, আর তারা প্রভাতে নিজ নিজ গৃহে উপুড় হয়ে পড়ে রইল।"),
    38: ("**وَعَادًا وَثَمُودَ** আর ‘আদ ও ছামূদ জাতিকে ধ্বংস করেছি； **وَقَدْ تَبَيَّنَ لَكُمْ** তোমাদের কাছে স্পষ্ট হয়েছে； **مِنْ مَسَاكِنِهِمْ** তাদের আবাসস্থল থেকে； **وَزَيَّنَ لَهُمُ الشَّيْطَانُ** শয়তান তাদের দৃষ্টিতে শোভিত করেছিল； **أَعْمَالَهُمْ** তাদের কৃতকর্ম； **فَصَدَّهُمْ عَنِ السَّبِيلِ** এবং পথ থেকে নিবৃত্ত করেছিল； **وَكَانُوا مُسْتَبْصِرِينَ** অথচ তারা ছিল বিচক্ষণ।", "আর আমি ধ্বংস করেছি ‘আদ ও ছামূদ জাতিকে; তাদের আবাসস্থল থেকেই তা তোমাদের কাছে স্পষ্ট হয়ে গেছে। শয়তান তাদের কৃতকর্মকে তাদের দৃষ্টিতে সুশোভিত করেছিল এবং তাদের সঠিক পথ থেকে নিবৃত্ত করেছিল, অথচ তারা ছিল বিচক্ষণ।"),
    39: ("**وَقَارُونَ وَفِرْعَوْنَ وَهَامَانَ** আর ক্বারূন, ফেরাউন ও হামানকে； **وَلَقَدْ جَاءَهُمْ مُوسَى** নিশ্চয় মূসা তাদের নিকট এসেছিল； **بِالْبَيِّنَاتِ** সুস্পষ্ট নিদর্শনসমূহ নিয়ে； **فَاسْتَكْبَرُوا فِي الْأَرْضِ** তারা জমিনে অহংকার করেছিল； **وَمَا كَانُوا سَابِقِينَ** তারা আমার পাকড়াও এড়াতে পারেনি।", "আর ক্বারূন, ফেরাউন ও হামানকেও; নিশ্চয় মূসা তাদের নিকট সুস্পষ্ট নিদর্শনসমূহ নিয়ে এসেছিল, কিন্তু তারা জমিনে ঔদ্ধত্য প্রদর্শন করেছিল; অথচ তারা আমার পাকড়াও এড়িয়ে যেতে পারেনি।"),
    40: ("**فَكُلًّا أَخَذْنَا** অতঃপর প্রত্যেককেই আমি পাকড়াও করেছি； **بِذَنْبِهِ** তার অপরাধের কারণে； **فَمِنْهُمْ مَنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا** কারও ওপর পাথরবর্ষী ঝড় পাঠিয়েছি； **وَمِنْهُمْ مَنْ أَخَذَتْهُ الصَّيْحَةُ** কাউকে গর্জন পাকড়াও করেছিল； **وَمِنْهُمْ مَنْ خَسَفْنَا بِهِ الْأَرْضَ** কাউকে ভূগর্ভে ধসিয়ে দিয়েছি； **وَمِنْهُمْ مَنْ أَغْرَقْنَا** কাউকে ডুবিয়ে দিয়েছি； **وَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ** আল্লাহ তাদের প্রতি জুলুম করেননি； **وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ** বরং তারা নিজেদের প্রতিই জুলুম করত।", "অতঃপর তাদের প্রত্যেককেই আমি তার অপরাধের কারণে পাকড়াও করেছিলাম: তাদের কারও ওপর আমি পাঠিয়েছিলাম পাথরবর্ষী প্রচণ্ড ঘূর্ণিঝড়, কাউকে গ্রাস করেছিল ভয়াবহ বিকট গর্জন, কাউকে আমি ভূগর্ভে ধসিয়ে দিয়েছিলাম এবং কাউকে আমি সাগরে ডুবিয়ে দিয়েছিলাম। বস্তুত আল্লাহ তাদের প্রতি কোনো জুলুম করেননি; বরং তারা নিজেরাই নিজেদের প্রতি জুলুম করেছিল।"),
    41: ("**مَثَلُ الَّذِينَ اتَّخَذُوا** যারা গ্রহণ করেছে তাদের দৃষ্টান্ত； **مِنْ دُونِ اللَّهِ أَوْلِيَاءَ** আল্লাহ ছাড়া অন্যকে অভিভাবক； **كَمَثَلِ الْعَنْكَبُوتِ** মাকড়সার ন্যায়； **اتَّخَذَتْ بَيْتًا** যে একটি ঘর বানায়； **وَإِنَّ أَوْهَنَ الْبُيُوتِ** অথচ সবচেয়ে দুর্বল ঘর； **لَبَيْتُ الْعَنْكَبُوتِ** নিশ্চয় মাকড়সার ঘর； **لَوْ كَانُوا يَعْلَمُونَ** যদি তারা জানত!", "যারা আল্লাহর পরিবর্তে অন্যকে অভিভাবক হিসেবে গ্রহণ করে, তাদের দৃষ্টান্ত মাকড়সার মতো, যে নিজের জন্য একটি ঘর বানায়; অথচ সমস্ত ঘরের মধ্যে সবচেয়ে দুর্বল ও ভঙ্গুর ঘর হলো মাকড়সার ঘর—যদি তারা জানত!"),
    42: ("**إِنَّ اللَّهَ يَعْلَمُ** নিশ্চয় আল্লাহ অবগত আছেন； **مَا يَدْعُونَ مِنْ دُونِهِ مِنْ شَيْءٍ** তাঁর পরিবর্তে তারা যাকে ডাকে সে যে কিছুই নয়； **وَهُوَ الْعَزِيزُ الْحَكِيمُ** আর তিনি পরাক্রমশালী, পরম প্রজ্ঞাময়।", "নিশ্চয় আল্লাহ জানেন তাঁর পরিবর্তে তারা যাকে ডাকে সে আসলে কিছুই নয়; আর তিনি পরাক্রমশালী, পরম প্রজ্ঞাময়।"),
    43: ("**وَتِلْكَ الْأَمْثَالُ** আর এইসব দৃষ্টান্ত； **نَضْرِبُهَا لِلنَّاسِ** মানুষের জন্য উপস্থাপন করি； **وَمَا يَعْقِلُهَا** কেবল তারাই তা বোঝে； **إِلَّا الْعَالِمُونَ** যারা জ্ঞানী।", "আর এই সকল দৃষ্টান্ত আমি মানুষের জন্য উপস্থাপন করি; কিন্তু কেবল জ্ঞানী ব্যক্তিরাই তা অনুধাবন করতে পারে।"),
    44: ("**خَلَقَ اللَّهُ** আল্লাহ সৃষ্টি করেছেন； **السَّمَاوَاتِ وَالْأَرْضَ** আকাশমণ্ডলী ও পৃথিবী； **بِالْحَقِّ** সত্যের সাথে； **إِنَّ فِي ذَلِكَ لَآيَةً** নিশ্চয় এতে বিরাট নিদর্শন রয়েছে； **لِلْمُؤْمِنِينَ** মুমিনদের জন্য।", "আল্লাহ আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন যথার্থ সত্যের সাথে; নিশ্চয় এতে মুমিনদের জন্য এক বিরাট নিদর্শন রয়েছে।"),
    45: ("**اتْلُ مَا أُوحِيَ إِلَيْكَ** তিলাওয়াত করুন যা ওহীযোগে এসেছে； **مِنْ الْكِتَابِ** কিতাব থেকে； **وَأَقِمِ الصَّلَاةَ** এবং সালাত কায়েম করুন； **إِنَّ الصَّلَاةَ تَنْهَى** নিশ্চয় সালাত বিরত রাখে； **عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ** অশ্লীল ও গর্হিত কাজ থেকে； **وَلَذِكْرُ اللَّهِ أَكْبَرُ** আল্লাহর স্মরণই সর্বশ্রেষ্ঠ； **وَاللَّهُ يَعْلَمُ مَا تَصْنَعُونَ** তোমরা যা করো আল্লাহ তা জানেন।", "তিলাওয়াত করুন যা ওহীযোগে আপনার প্রতি কিতাব থেকে অবতীর্ণ করা হয়েছে এবং সালাত কায়েম করুন; নিশ্চয় সালাত অশ্লীল ও গর্হিত কাজ থেকে বিরত রাখে। আর আল্লাহর স্মরণই সর্বশ্রেষ্ঠ; আর তোমরা যা করো আল্লাহ তা সম্যক অবগত আছেন।"),
    46: ("**وَلَا تُجَادِلُوا** আর তোমরা বিতর্ক কোরো না； **أَهْلَ الْكِتَابِ** আহলে কিতাবের সাথে； **إِلَّا بِالَّتِي هِيَ أَحْسَنُ** উত্তম পন্থা ছাড়া； **إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ** তবে যালেমরা ব্যতীত； **وَقُولُوا آمَنَّا** এবং বলো: আমরা ঈমান এনেছি； **بِالَّذِي أُنْزِلَ إِلَيْنَا** যা আমাদের প্রতি নাযিল হয়েছে； **وَأُنْزِلَ إِلَيْكُمْ** এবং তোমাদের প্রতি নাযিল হয়েছে； **وَإِلَهُنَا وَإِلَهُكُمْ وَاحِدٌ** আমাদের ও তোমাদের ইলাহ এক； **وَنَحْنُ لَهُ مُسْلِمُونَ** আমরা তাঁরই অনুগত।", "আর তোমরা কিতাবধারীদের সাথে উত্তম পন্থা ছাড়া বিতর্ক কোরো না—তবে তাদের মধ্যে যারা জুলুম করেছে তাদের সাথে ভিন্ন কথা; এবং বলো: আমরা ঈমান এনেছি যা আমাদের প্রতি অবতীর্ণ হয়েছে এবং যা তোমাদের প্রতি অবতীর্ণ হয়েছে তাতে; আর আমাদের ইলাহ ও তোমাদের ইলাহ তো একই, এবং আমরা তাঁরই প্রতি অনুগত (মুসলিম)।"),
    47: ("**وَكَذَلِكَ أَنْزَلْنَا إِلَيْكَ الْكِتَابَ** এভাবেই আপনার প্রতি কিতাব অবতীর্ণ করেছি； **فَالَّذِينَ آتَيْنَاهُمُ الْكِتَابَ** যাদের কিতাব দিয়েছি； **يُؤْمِنُونَ بِهِ** তারা এতে ঈমান আনে； **وَمِنْ هَؤُلَاءِ مَنْ يُؤْمِنُ بِهِ** এদের থেকেও কেউ কেউ ঈমান আনে； **وَمَا يَجْحَدُ بِآيَاتِنَا** আমার আয়াত কেবল তারাই অস্বীকার করে； **إِلَّا الْكَافِرُونَ** যারা চরম কাফির।", "আর এভাবেই আমি আপনার প্রতি কিতাব অবতীর্ণ করেছি; সুতরাং যাদের আমি কিতাব দিয়েছি তারা এতে ঈমান আনে; আর এদের (মক্কাবাসীদের) মধ্য থেকেও কেউ কেউ এতে ঈমান আনে; আর কাফিররা ছাড়া আর কেউই আমার আয়াতসমূহ অস্বীকার করে না।"),
    48: ("**وَمَا كُنْتَ تَتْلُو** আপনি তিলাওয়াত করতেন না； **مِنْ قَبْلِهِ مِنْ كِتَابٍ** এর পূর্বে কোনো কিতাব； **وَلَا تَخُطُّهُ بِيَمِينِكَ** ডান হাতে লিখতেনও না； **إِذًا لَارْتَابَ الْمُبْطِلُونَ** তেমন হলে বাতিলপন্থীরা সন্দেহে পড়ত।", "আর আপনি তো এর পূর্বে কোনো কিতাব তিলাওয়াত করতেন না এবং নিজের ডান হাত দিয়ে কোনো কিছু লিখতেনও না; তেমন হলে বাতিলপন্থীরা অবশ্যই সন্দেহে পতিত হতো।"),
    49: ("**بَلْ هُوَ آيَاتٌ بَيِّنَاتٌ** বরং এটি সুস্পষ্ট নিদর্শনাবলী； **فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ** যাদের জ্ঞান দেওয়া হয়েছে তাদের বক্ষে； **وَمَا يَجْحَدُ بِآيَاتِنَا** আর আমার আয়াত কেবল তারাই অস্বীকার করে； **إِلَّا الظَّالِمُونَ** যারা চরম যালেম।", "বরং যাদের জ্ঞান দান করা হয়েছে তাদের বক্ষসমূহে এটি সুস্পষ্ট নিদর্শনাবলী; আর যালেমরা ছাড়া আর কেউই আমার আয়াতসমূহকে অস্বীকার করে না।"),
    50: ("**وَقَالُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَاتٌ** তারা বলে: তার ওপর মোজেযা আসল না কেন； **مِنْ رَبِّهِ** তার রবের পক্ষ থেকে?； **قُلْ إِنَّمَا الْآيَاتُ عِنْدَ اللَّهِ** বলুন: নিদর্শনসমূহ তো আল্লাহরই ইখতিয়ারে； **وَإِنَّمَا أَنَا نَذِيرٌ مُبِينٌ** আমি তো কেবল সুস্পষ্ট সতর্ককারী।", "আর তারা বলে: তার রবের পক্ষ থেকে তার প্রতি মোজেযা অবতীর্ণ হলো না কেন? বলুন: মোজেযা তো কেবল আল্লাহরই ইখতিয়ারে; আর আমি তো কেবল এক সুস্পষ্ট সতর্ককারী।"),
    51: ("**أَوَلَمْ يَكْفِهِمْ** তাদের জন্য কি যথেষ্ট নয়； **أَنَّا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ** যে আমি আপনার ওপর কিতাব অবতীর্ণ করেছি； **يُتْلَى عَلَيْهِمْ** যা তাদের কাছে পাঠ করা হয়?； **إِنَّ فِي ذَلِكَ لَرَحْمَةً** নিশ্চয় এতে রহমত রয়েছে； **وَذِكْرَى** এবং উপদেশ； **لِقَوْمٍ يُؤْمِنُونَ** ঈমানদার সম্প্রদায়ের জন্য।", "তাদের জন্য কি এটিই যথেষ্ট নয় যে আমি আপনার প্রতি কিতাব অবতীর্ণ করেছি যা তাদের কাছে পাঠ করা হয়? নিশ্চয় এতে রয়েছে রহমত ও উপদেশ সেই সম্প্রদায়ের জন্য যারা ঈমান আনে।"),
    52: ("**قُلْ كَفَى بِاللَّهِ** বলুন: আল্লাহই যথেষ্ট； **بَيْنِي وَبَيْنَكُمْ شَهِيدًا** আমার ও তোমাদের মাঝে সাক্ষী হিসেবে； **يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ** তিনি জানেন যা আসমান ও জমিনে আছে； **وَالَّذِينَ آمَنُوا بِالْبَاطِلِ** আর যারা অসত্যে বিশ্বাস করেছে； **وَكَفَرُوا بِاللَّهِ** এবং আল্লাহকে অস্বীকার করেছে； **أُولَئِكَ هُمُ الْخَاسِرُونَ** তারাই ক্ষতিগ্রস্ত।", "বলুন: আমার ও তোমাদের মাঝে সাক্ষী হিসেবে আল্লাহই যথেষ্ট; আকাশমণ্ডলী ও পৃথিবীতে যা কিছু আছে তা তিনি অবগত আছেন। আর যারা অসত্যে বিশ্বাস করেছে এবং আল্লাহকে অস্বীকার করেছে, তারাই তো ক্ষতিগ্রস্ত।"),
    53: ("**وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ** তারা আপনার কাছে আযাব ত্বরান্বিত করতে চায়； **وَلَوْلَا أَجَلٌ مُسَمًّى** নির্দিষ্ট সময় না থাকলে； **لَجَاءَهُمُ الْعَذَابُ** অবশ্যই আযাব নেমে আসত； **وَلَيَأْتِيَنَّهُمْ بَغْتَةً** আর তা আকস্মিকভাবে আসবে； **وَهُمْ لَا يَشْعُرُونَ** যখন তারা টেরও পাবে না।", "আর তারা আপনার কাছে আযাব ত্বরান্বিত করতে চায়; যদি একটি নির্ধারিত সময় নির্দিষ্ট না থাকত তবে তাদের ওপর অবশ্যই আযাব নেমে আসত; আর তা অবশ্যই তাদের ওপর আকস্মিকভাবে আসবে যখন তারা তা টেরও পাবে না।"),
    54: ("**يَسْتَعْجِلُونَكَ بِالْعَذَابِ** তারা আপনার কাছে আযাব ত্বরান্বিত করতে চায়； **وَإِنَّ جَهَنَّمَ** আর নিশ্চয় জাহান্নাম； **لَمُحِيطَةٌ بِالْكَافِرِينَ** কাফিরদের পরিবেষ্টন করেই রেখেছে।", "তারা আপনার কাছে আযাব ত্বরান্বিত করতে চায়; আর জাহান্নাম তো কাফিরদের পরিবেষ্টন করেই রেখেছে।"),
    55: ("**يَوْمَ يَغْشَاهُمُ الْعَذَابُ** যেদিন আযাব তাদের গ্রাস করবে； **مِنْ فَوْقِهِمْ** তাদের ওপর থেকে； **وَمِنْ تَحْتِ أَرْجُلِهِمْ** এবং তাদের পায়ের নিচ থেকে； **وَيَقُولُ ذُوقُوا** এবং তিনি বলবেন: স্বাদ আস্বাদন করো； **مَا كُنْتُمْ تَعْمَلُونَ** যা তোমরা করতে।", "যেদিন আযাব তাদের গ্রাস করবে তাদের উপর থেকে এবং তাদের পায়ের নিচ থেকে, আর তিনি বলবেন: তোমরা যা করতে তার স্বাদ আস্বাদন করো!"),
    56: ("**يَا عِبَادِيَ الَّذِينَ آمَنُوا** হে আমার মুমিন বান্দাগণ!； **إِنَّ أَرْضِي وَاسِعَةٌ** নিশ্চয় আমার পৃথিবী প্রশস্ত； **فَإِيَّايَ فَاعْبُدُونِ** অতএব কেবল আমারই ইবাদত করো।", "হে আমার মুমিন বান্দাগণ! নিশ্চয় আমার পৃথিবী প্রশস্ত; অতএব তোমরা কেবল আমারই ইবাদত করো।"),
    57: ("**كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ** প্রতিটি প্রাণকেই মৃত্যুর স্বাদ নিতে হবে； **ثُمَّ إِلَيْنَا تُرْجَعُونَ** অতঃপর আমারই কাছে প্রত্যাবর্তিত হবে।", "প্রতিটি প্রাণকেই মৃত্যুর স্বাদ গ্রহণ করতে হবে; অতঃপর আমারই সমীপে তোমাদের প্রত্যাবর্তিত করা হবে।"),
    58: ("**وَالَّذِينَ آمَنُوا** আর যারা ঈমান এনেছে； **وَعَمِلُوا الصَّالِحَاتِ** এবং সৎকর্ম করেছে； **لَنُبَوِّئَنَّهُمْ مِنَ الْجَنَّةِ غُرَفًا** জান্নাতে তাদের সুউচ্চ প্রাসাদ দেব； **تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ** যার তলদেশ দিয়ে নদী বইছে； **خَالِدِينَ فِيهَا** সেখানে তারা চিরকাল থাকবে； **نِعْمَ أَجْرُ الْعَامِلِينَ** আমলকারীদের প্রতিদান কতই না চমৎকার!", "আর যারা ঈমান এনেছে এবং সৎকর্ম করেছে, আমি অবশ্যই জান্নাতে তাদের সুউচ্চ প্রাসাদে স্থান দেব, যার তলদেশ দিয়ে নদীসমূহ প্রবাহিত, সেখানে তারা চিরকাল থাকবে; আমলকারীদের প্রতিদান কতই না চমৎকার!"),
    59: ("**الَّذِينَ صَبَرُوا** যারা ধৈর্য ধারণ করেছে； **وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ** এবং নিজেদের রবের ওপর ভরসা রাখে।", "যারা ধৈর্য ধারণ করেছে এবং নিজেদের রবের ওপর ভরসা রাখে।"),
    60: ("**وَكَأَيِّنْ مِنْ دَابَّةٍ** আর কত জীবজন্তু রয়েছে； **لَا تَحْمِلُ رِزْقَهَا** যারা রিযিক সঞ্চয় করে না； **اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ** আল্লাহই তাদের ও তোমাদের রিযিক দেন； **وَهُوَ السَّمِيعُ الْعَلِيمُ** আর তিনি সর্বশ্রোতা, সর্বজ্ঞ।", "আর কত জীবজন্তু রয়েছে যারা নিজেদের রিযিক সঞ্চয় করে রাখে না; আল্লাহই তাদের এবং তোমাদের রিযিক দান করেন; আর তিনি সর্বশ্রোতা, সর্বজ্ঞ।"),
    61: ("**وَلَئِنْ سَأَلْتَهُمْ** আর যদি তাদের জিজ্ঞেস করেন； **مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ** কে আকাশ ও পৃথিবী সৃষ্টি করেছেন； **وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ** এবং সূর্য ও চন্দ্র নিয়োজিত রেখেছেন； **لَيَقُولُنَّ اللَّهُ** তারা অবশ্যই বলবে: আল্লাহ； **فَأَنَّى يُؤْفَكُونَ** তবে তারা কোথায় বিভ্রান্ত হচ্ছে?", "আর আপনি যদি তাদের জিজ্ঞেস করেন কে আকাশমণ্ডলী ও পৃথিবী সৃষ্টি করেছেন এবং সূর্য ও চন্দ্রকে নিয়োজিত রেখেছেন, তবে তারা অবশ্যই বলবে: ‘আল্লাহ’। তাহলে তারা কোথায় বিভ্রান্ত হয়ে ঘুরপাক খাচ্ছে?"),
    62: ("**اللَّهُ يَبْسُطُ الرِّزْقَ** আল্লাহ রিযিক প্রশস্ত করেন； **لِمَنْ يَشَاءُ مِنْ عِبَادِهِ** তাঁর বান্দাদের মধ্যে যার জন্য ইচ্ছা； **وَيَقْدِرُ لَهُ** এবং যার জন্য ইচ্ছা সংকীর্ণ করেন； **إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ** নিশ্চয় আল্লাহ সর্ববিষয়ে সম্যক অবগত।", "আল্লাহ তাঁর বান্দাদের মধ্যে যার জন্য ইচ্ছা রিযিক প্রশস্ত করে দেন এবং যার জন্য ইচ্ছা তা সংকীর্ণ করেন; নিশ্চয় আল্লাহ সর্ববিষয়ে সম্যক অবগত।"),
    63: ("**وَلَئِنْ سَأَلْتَهُمْ** আর যদি তাদের জিজ্ঞেস করেন； **مَنْ نَزَّلَ مِنَ السَّمَاءِ مَاءً** কে আকাশ থেকে পানি বর্ষণ করেন； **فَأَحْيَا بِهِ الْأَرْضَ** অতঃপর তা দিয়ে জমিন পুনরুজ্জীবিত করেন； **مِنْ بَعْدِ مَوْتِهَا** তার মৃত্যুর পর； **لَيَقُولُنَّ اللَّهُ** তারা অবশ্যই বলবে: আল্লাহ； **قُلِ الْحَمْدُ لِلَّهِ** বলুন: সমস্ত প্রশংসা আল্লাহর； **بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ** কিন্তু তাদের অধিকাংশই বোঝে না।", "আর আপনি যদি তাদের জিজ্ঞেস করেন কে আকাশ থেকে বৃষ্টি বর্ষণ করেন এবং তা দ্বারা জমিনকে তার মৃত্যুর পর পুনরুজ্জীবিত করেন, তবে তারা অবশ্যই বলবে: ‘আল্লাহ’। বলুন: সমস্ত প্রশংসা আল্লাহরই; কিন্তু তাদের অধিকাংশই তা অনুধাবন করে না।"),
    64: ("**وَمَا هَذِهِ الْحَيَاةُ الدُّنْيَا** আর এই পার্থিব জীবন নয়； **إِلَّا لَهْوٌ وَلَعِبٌ** খেল-তামাশা ও চিত্তবিনোদন ছাড়া； **وَإِنَّ الدَّارَ الْآخِرَةَ** আর নিশ্চয় আখেরাতের আবাস； **لَهِيَ الْحَيَوَانُ** তা-ই তো প্রকৃত চিরস্থায়ী জীবন； **لَوْ كَانُوا يَعْلَمُونَ** যদি তারা জানত!", "আর এই পার্থিব জীবন তো খেল-তামাশা ও চিত্তবিনোদন ছাড়া আর কিছুই নয়; আর আখেরাতের আবাসই হলো প্রকৃত চিরস্থায়ী জীবন—যদি তারা জানত!"),
    65: ("**فَإِذَا رَكِبُوا فِي الْفُلْكِ** অতঃপর যখন তারা নৌযানে চড়ে； **دَعَوُا اللَّهَ** আল্লাহকে ডাকে； **مُخْلِصِينَ لَهُ الدِّينَ** দ্বীনকে তাঁর জন্য একনিষ্ঠ করে； **فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ** যখন স্থলে পৌঁছে দেন； **إِذَا هُمْ يُشْرِكُونَ** তখনই তারা শরিক করে!", "অতঃপর যখন তারা নৌযানে আরোহণ করে, তখন তারা দ্বীনকে একমাত্র আল্লাহর জন্য একনিষ্ঠ করে তাঁকে কাতরভাবে ডাকে; অতঃপর যখন তিনি তাদের উদ্ধার করে স্থলে পৌঁছে দেন, তখনই তারা শিরকে লিপ্ত হয়!"),
    66: ("**لِيَكْفُرُوا بِمَا آتَيْنَاهُمْ** যাতে অকৃতজ্ঞতা প্রকাশ করে যা আমি দিয়েছি； **وَلِيَتَمَتَّعُوا** এবং তারা ভোগ করে নেয়； **فَسَوْفَ يَعْلَمُونَ** শীঘ্রই তারা জানতে পারবে।", "যাতে তারা অকৃতজ্ঞতা প্রকাশ করে যা আমি তাদের দিয়েছি তার প্রতি, এবং ভোগ করে নেয়; অতঃপর শীঘ্রই তারা তা জানতে পারবে।"),
    67: ("**أَوَلَمْ يَرَوْا** তারা কি লক্ষ্য করে না； **أَنَّا جَعَلْنَا حَرَمًا آمِنًا** আমি নিরাপদ হারাম বানিয়েছি； **وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ** অথচ চারপাশ থেকে মানুষকে ছিনিয়ে নেওয়া হয়； **أَفَبِالْبَاطِلِ يُؤْمِنُونَ** তবুও কি তারা অসত্যে বিশ্বাস করবে； **وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ** এবং আল্লাহর নিয়ামত অস্বীকার করবে?", "তারা কি লক্ষ্য করে না যে আমি এক নিরাপদ হারাম (মক্কা) প্রতিষ্ঠিত করেছি, অথচ তাদের চারপাশ থেকে মানুষকে ছিনিয়ে নেওয়া হয়? তবুও কি তারা অসত্যে বিশ্বাস করবে এবং আল্লাহর নিয়ামতকে অস্বীকার করবে?"),
    68: ("**وَمَنْ أَظْلَمُ** আর তার চেয়ে বড় যালেম কে； **مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا** যে আল্লাহর প্রতি মিথ্যা আরোপ করে； **أَوْ كَذَّبَ بِالْحَقِّ** অথবা সত্যকে অস্বীকার করে； **لَمَّا جَاءَهُ** যখন তা তার নিকট আসল?； **أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْكَافِرِينَ** জাহান্নামেই কি কাফিরদের আবাস নয়?", "আর তার চেয়ে বড় যালেম আর কে হতে পারে, যে আল্লাহর প্রতি মিথ্যা আরোপ করে অথবা তার নিকট সত্য আসার পর তাকে অস্বীকার করে? জাহান্নামেই কি কাফিরদের আবাসস্থল নয়?"),
    69: ("**وَالَّذِينَ جَاهَدُوا فِينَا** আর যারা আমার পথে সর্বাত্মক সাধনা করে； **لَنَهْدِيَنَّهُمْ سُبُلَنَا** আমি অবশ্যই তাদের আমার পথ দেখাব； **وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ** নিশ্চয় আল্লাহ সৎকর্মশীলদের সাথে আছেন।", "আর যারা আমার পথে সর্বাত্মক জিহাদ ও সাধনা করে, আমি অবশ্যই তাদের আমার পথসমূহের সন্ধান দেব; আর নিশ্চয় আল্লাহ সৎকর্মশীলদের সাথেই আছেন।")
}
